    private void refillBuffer() throws IOException {
        curPos = 0;
        endPos = -1;
        int readed;
        while (reader.ready() && (readed = reader.read(buf, endPos + 1, buf.length - endPos - 1)) >= 0 &&
                endPos < buf.length - 1) {
            endPos += readed;
        }
        if (endPos < 0 && previous != null) {
            buf = previous.buf;
            reader = previous.reader;
            curPos = previous.curPos;
            endPos = previous.endPos;
            currentRow = previous.currentRow;
            currentColumn = previous.currentColumn;
            previous = previous.previous;
            parser.endOfInclude();
            if (curPos > endPos) {
                refillBuffer();
            }
        }
    }

